<div class="form-grid"><label class="field">Assignment title<input name="title" required maxlength="255" value="{{ $assignment->title ?? '' }}"></label><label class="field">Deadline (optional)<input name="due_at" type="datetime-local" value="{{ isset($assignment->due_at) ? \Carbon\Carbon::parse($assignment->due_at)->format('Y-m-d\TH:i') : '' }}"></label><label class="field">Maximum score<input type="number" name="max_score" min="1" max="10000" required value="{{ $assignment->max_score ?? 100 }}"></label><label class="field">Passing score<input type="number" name="pass_score" min="0" required value="{{ $assignment->pass_score ?? 50 }}"></label><label class="field full">Instructions<textarea name="instructions" required maxlength="100000" rows="5">{{ $assignment->instructions ?? '' }}</textarea></label></div><label class="field"><input type="checkbox" name="published" value="1" @checked($assignment->published ?? false)>Published / required for completion</label><button>Save assignment</button>
